std::map<SwtEntryIndex, SwtEntry> Client::swtTable() {
    std::map<SwtEntryIndex, SwtEntry> rows;
    c_.walk(oids::swtEntry, [&rows](const snmpwrap::VarBind& vb) {
        if (vb.oid.size() <= oids::swtEntry.size() + 1) return true;
        const auto i = SwtEntryIndex::fromOid(cellIndex(oids::swtEntry, vb.oid));
        if (!i) return true;
        SwtEntry& row = rows[*i];
        switch (vb.oid[oids::swtEntry.size()]) {
            case 2:
                if (vb.value.type() == snmpwrap::Type::OctetString) row.swtEntryName = vb.value.asString();
                break;
            case 3:
                if (vb.value.type() == snmpwrap::Type::Gauge32) row.swtEntryValue = vb.value.asUInt();
                break;
            case 4:
                if (vb.value.type() == snmpwrap::Type::Integer) row.swtEntryStatus = static_cast<SwtEntryStatus>(vb.value.asInt());
                break;
            default: break;
        }
        (void)row;
        return true;
    });
    return rows;
}

