void Client::createSwtRowEntry(const SwtRowEntryIndex& index, const SwtRowEntryValues& values, bool activate) {
    const snmpwrap::Oid idx = index.toOid();
    std::vector<snmpwrap::VarBind> sets;
    if (values.swtRowName) {
        snmpwrap::Value v = snmpwrap::Value::string(*values.swtRowName);
        check_swtRowName(v);
        sets.push_back({oids::swtRowName + idx, std::move(v)});
    }
    if (values.swtRowValue) {
        snmpwrap::Value v = snmpwrap::Value::gauge(*values.swtRowValue);
        check_swtRowValue(v);
        sets.push_back({oids::swtRowValue + idx, std::move(v)});
    }
    sets.push_back({oids::swtRowStatus + idx, snmpwrap::Value::integer(static_cast<std::int32_t>(activate ? snmpwrap::RowStatus::CreateAndGo : snmpwrap::RowStatus::CreateAndWait))});
    c_.set(sets);
}

